const inputs = $input.all();
const splitItems = $('Split Countries').all();

return inputs.map((item, index) => {
  const html = item.json.data || '';
  const splitItem = splitItems[index]?.json || {};
  const location_id = splitItem.location_id;
  const country_name = splitItem.name;

  const pageMatch = html.match(/Page\s+\d+\s+of\s+(\d+)/);
  const totalPages = pageMatch ? parseInt(pageMatch[1]) : 1;

  console.log(`[${country_name}] Total pages: ${totalPages}`);

  return { json: { location_id, country_name, totalPages } };
});

return $input.all().flatMap(item => {
  const { location_id, country_name, totalPages } = item.json;
  const pages = [];

  for (let page = 1; page <= totalPages; page++) {
    pages.push({ json: { url: `https://rcdb.com/r.htm?ot=2&ol=${location_id}&page=${page}`, page, location_id, country_name } });
  }

  console.log(`[${country_name}] Generated ${pages.length} page URLs`);
  return pages;
});

const results = [];

for (const item of $input.all()) {
  const html = item.json.data || '';
  const page = item.json.page || '?';

  // Match each table row
  const rowRegex = /<tr[^>]*>([\s\S]*?)(?=<tr|<\/tbody|<\/table|$)/gi;
  let rowMatch;

  while ((rowMatch = rowRegex.exec(html)) !== null) {
    const row = rowMatch[1];
    // RCDB uses unquoted hrefs: href=/1234.htm
    const linkRegex = /href=\/(\d+)\.htm[^>]*>([^<]+)<\/a>/g;
    const links = [];
    let linkMatch;

    while ((linkMatch = linkRegex.exec(row)) !== null) {
      links.push({ rcdb_id: linkMatch[1], name: linkMatch[2].trim() });
    }

    if (links.length >= 2) {
      results.push({
        coaster_rcdb_id: links[0].rcdb_id,
        coaster_name: links[0].name,
        park_rcdb_id: links[1].rcdb_id,
        park_name: links[1].name
      });
    }
  }
}

console.log(`Total coaster/park pairs: ${results.length}`);
return results.map(r => ({ json: r }));

const allItems = $input.all();
const coastersMap = {};
const parksMap = {};
for (const item of allItems) {
  const d = item.json;
  if (!d.coaster_rcdb_id || !d.park_rcdb_id) continue;
  coastersMap[d.coaster_rcdb_id] = { coaster_rcdb_id: d.coaster_rcdb_id, coaster_name: d.coaster_name, park_rcdb_id: d.park_rcdb_id };
  parksMap[d.park_rcdb_id] = { rcdb_id: d.park_rcdb_id, name: d.park_name };
}
const parks = Object.values(parksMap);
const coasters = Object.values(coastersMap);
console.log(`Deduplicated: ${parks.length} unique parks, ${coasters.length} unique coasters`);
return parks.map(p => ({ json: { ...p, _all_coasters: coasters.filter(c => c.park_rcdb_id === p.rcdb_id) } }));

const items = $input.all();
const dedupItems = $('Deduplicate Parks & Coasters').all();

// RCDB status IDs confirmed by inspecting real park pages:
//   id=93  → Operating          (e.g. rcdb.com/4546.htm)
//   id=310 → Under Construction (e.g. rcdb.com/22331.htm)
//   id=311 → SBNO               (e.g. rcdb.com/10339.htm)
//   id=318 → Operated/Defunct   (e.g. rcdb.com/4946.htm)
// Strategy: match the FIRST g.htm?id= in the HTML — that is always the
// current official status shown right below the park name. Any later
// occurrences (defunct coasters, historical SBNO entries) are ignored.
const STATUS_MAP = { '93': 'operating', '310': 'under_construction', '311': 'sbno', '318': 'defunct' };

// Coaster status is derived from which section heading the coaster appears under
// on the park page. The actual HTML uses <h4> tags:
//   <h4>Defunct Roller Coasters: <a href="...">4</a></h4>
// Possible sections:
//   "Operating Roller Coasters"          → 'operating'
//   "SBNO Roller Coasters"               → 'sbno'
//   "Defunct Roller Coasters"            → 'defunct'
//   "Roller Coasters Under Construction" → 'under_construction'
const SECTION_STATUS_MAP = {
  'operating roller coasters': 'operating',
  'sbno roller coasters': 'sbno',
  'defunct roller coasters': 'defunct',
  'roller coasters under construction': 'under_construction',
};

return items.map((item, index) => {
  const rawItem = item.json;
  const dedupItem = dedupItems[index]?.json || {};

  if (rawItem.error || !rawItem.data) {
    const rcdb_id = dedupItem.rcdb_id;
    console.error(`[Park ${rcdb_id}] HTTP error:`, rawItem.error || 'no data');
    return { json: { rcdb_id, name: null, city: null, country: null, latitude: null, longitude: null, status: 'operating', coasterStatusMap: {}, _error: true } };
  }

  const html = rawItem.data;
  const rcdb_id = dedupItem.rcdb_id;
  const _all_coasters = dedupItem._all_coasters || [];

  const nameMatch = html.match(/<h1>([^<]+)<\/h1>/);
  const name = nameMatch ? nameMatch[1].trim() : null;

  const coordMatch = html.match(/google\.com\/maps\/place\/(-?\d+\.\d+),(-?\d+\.\d+)/);
  const latitude = coordMatch ? parseFloat(coordMatch[1]) : null;
  const longitude = coordMatch ? parseFloat(coordMatch[2]) : null;

  const locationLinkRegex = /location\.htm\?id=\d+">([^<]+)<\/a>/g;
  const locationParts = [];
  let locMatch;
  while ((locMatch = locationLinkRegex.exec(html)) !== null) {
    locationParts.push(locMatch[1].trim());
  }

  let city = null, country = null;
  if (locationParts.length >= 3) { city = locationParts[0]; country = locationParts[locationParts.length - 1]; }
  else if (locationParts.length === 2) { city = locationParts[0]; country = locationParts[1]; }
  else if (locationParts.length === 1) { country = locationParts[0]; }

  const firstStatusMatch = html.match(/g\.htm\?id=(\d+)/);
  const status = firstStatusMatch ? (STATUS_MAP[firstStatusMatch[1]] ?? 'operating') : 'operating';

  // Build coasterStatusMap from raw HTML <h4> section headings.
  // Strategy: find each <h4> containing "Roller Coasters", record its status,
  // then collect all href=/{id}.htm links until the next <h4>, </section>, or <h3>.
  const coasterStatusMap = {};
  const sectionRegex = /<h4>([^<]*Roller Coasters[^<]*):.*?<\/h4>([\s\S]*?)(?=<h4>|<\/section>|<h3>|$)/gi;
  const coasterLinkRegex = /href=\/?(\d+)\.htm/g;
  let sectionMatch;
  while ((sectionMatch = sectionRegex.exec(html)) !== null) {
    const headingKey = sectionMatch[1].trim().toLowerCase();
    const sectionStatus = SECTION_STATUS_MAP[headingKey] ?? 'operating';
    const sectionBody = sectionMatch[2];
    coasterLinkRegex.lastIndex = 0;
    let linkMatch;
    while ((linkMatch = coasterLinkRegex.exec(sectionBody)) !== null) {
      coasterStatusMap[linkMatch[1]] = sectionStatus;
    }
  }

  console.log(`[Park ${rcdb_id}] name=${name}, city=${city}, country=${country}, lat=${latitude}, lng=${longitude}, status=${status}, coasters_with_status=${Object.keys(coasterStatusMap).length}`);

  return { json: { rcdb_id, name, city, country, latitude, longitude, status, coasterStatusMap, _all_coasters, synced_at: new Date().toISOString() } };
});

// This node receives items from two paths:
// - input[0]: parks that went through Nominatim (latitude was null)
// - input[1]: parks that already had coordinates (bypassed Nominatim)
//
// For Nominatim items, $input.item.json contains the raw geocode response
// and we retrieve park data from 'Needs Geocoding?' TRUE branch.
// For bypass items, $input.item.json is already the full park object.

const results = [];

// Path 1: items that went through Nominatim (input index 0)
const nominatimItems = $input.all();
const needsGeocodingItems = $('Needs Geocoding?').all(); // TRUE branch output

// We track which rcdb_ids came through the geocode path
const geocodedIds = new Set();

for (let i = 0; i < nominatimItems.length; i++) {
  const geoItem = nominatimItems[i];
  // Items from Nominatim path: geoItem.json is the geocode API response (array)
  // We need the corresponding park from 'Needs Geocoding?' TRUE output
  const park = needsGeocodingItems[i]?.json || {};

  let latitude = park.latitude;
  let longitude = park.longitude;

  // latitude should be null here since this is the geocode path
  if (latitude === null || latitude === undefined) {
    const raw = geoItem.json;
    const geoData = Array.isArray(raw) ? raw[0] : (raw?.lat ? raw : null);
    if (geoData && geoData.lat && geoData.lon) {
      latitude = parseFloat(geoData.lat);
      longitude = parseFloat(geoData.lon);
      console.log(`[Park ${park.rcdb_id}] Geocoded via Nominatim: lat=${latitude}, lng=${longitude}`);
    } else {
      console.warn(`[Park ${park.rcdb_id}] Nominatim returned no results for city=${park.city}, country=${park.country}. Using 0,0 as fallback.`);
      latitude = 0;
      longitude = 0;
    }
  }

  geocodedIds.add(park.rcdb_id);
  results.push({ json: { ...park, latitude, longitude } });
}

console.log(`Merge Coordinates: ${results.length} geocoded, passed through with existing coords handled upstream.`);
return results;

const coastersMap = {};
for (const item of $input.all()) {
  const coasters = item.json._all_coasters || [];
  const coasterStatusMap = item.json.coasterStatusMap || {};
  for (const c of coasters) {
    if (c.coaster_rcdb_id) {
      // Resolve status from the park page section headings; fallback to 'operating'
      const status = coasterStatusMap[String(c.coaster_rcdb_id)] ?? 'operating';
      coastersMap[c.coaster_rcdb_id] = { ...c, status };
    }
  }
}
const coasters = Object.values(coastersMap);
console.log(`Emitting ${coasters.length} coasters for upsert`);
return coasters.map(c => ({ json: c }));

// Upsert Coaster uses executeQuery which returns 1 result item per execution,
// not one per row. Use Emit Coasters count as the source of truth for how
// many coasters were sent for upsert, and check upsert results for errors.
const emitCoasterItems = $('Emit Coasters').all();
const coasterResults = $input.all();
const parkResults = $('Upsert Park').all();
const mergeCoordResults = $('Merge Coordinates').all();

// continueOnFail nodes surface errors as { error: '...' } on the item
const coasterErrors = coasterResults.filter(r => r.json.error);
const parkErrors = parkResults.filter(r => r.json.error);
const geocodeFallbacks = mergeCoordResults.filter(r => r.json.latitude === 0 && r.json.longitude === 0);

const summary = {
  done: true,
  parks_upserted: parkResults.length - parkErrors.length,
  parks_errors: parkErrors.length,
  coasters_upserted: emitCoasterItems.length,
  coasters_errors: coasterErrors.length,
  geocode_fallbacks: geocodeFallbacks.length,
  timestamp: new Date().toISOString()
};

console.log(`[RCDB Scraper] Done.
  Parks upserted: ${summary.parks_upserted} (${summary.parks_errors} errors)
  Coasters upserted: ${summary.coasters_upserted} (${summary.coasters_errors} errors)
  Geocode fallbacks (0,0): ${summary.geocode_fallbacks}
  Timestamp: ${summary.timestamp}`);

return [{ json: summary }];

const item = $input.first().json;
// n8n passes error workflow data under item.execution and item.workflow
const execution = item.execution || {};
const error = execution.error || {};
const workflow = item.workflow || {};

const summary = {
  error: true,
  message: error.message || 'Unknown error',
  node: execution.lastNodeExecuted || 'unknown',
  execution_id: execution.id || 'unknown',
  workflow_name: workflow.name || 'RCDB Scraper',
  timestamp: new Date().toISOString()
};

console.error('[RCDB Scraper] Critical error:', JSON.stringify(summary, null, 2));

return [{ json: summary }];

